{
  "implementation": "def solve(case):
    # Validate payload structure
    required_fields = ['initial_state', 'max_steps', 'tool_observations', 'transitions']
    for field in required_fields:
        if field not in case:
            raise ValueError(f"Missing required field: {field}")

    initial_state = case['initial_state']
    max_steps = case['max_steps']
    tool_obs = case['tool_observations']
    transitions = case['transitions']

    # Validate initial state exists
    if initial_state not in transitions:
        raise ValueError(f"Initial state '{initial_state}' not in transitions")

    # Validate all action states have required subfields and tools exist
    for state_name, state_def in transitions.items():
        if not isinstance(state_def, dict):
            raise ValueError(f"State '{state_name}' must be a dict")
        if 'kind' not in state_def:
            raise ValueError(f"State '{state_name}' missing 'kind'")
        kind = state_def['kind']
        if kind == 'final':
            if 'value' not in state_def:
                raise ValueError(f"Final state '{state_name}' missing 'value'")
        elif kind == 'action':
            if 'action' not in state_def:
                raise ValueError(f"Action state '{state_name}' missing 'action'")
            action = state_def['action']
            if action not in tool_obs:
                raise ValueError(f"Tool '{action}' referenced by state '{state_name}' not in tool_observations")
            # Validate default_next exists in transitions (or can be None? but spec implies always present? We'll check)
            # Actually default_next is required per schema? The payload example has it. We'll validate presence.
            if 'default_next' not in state_def:
                raise ValueError(f"Action state '{state_name}' missing 'default_next'")
            default_next = state_def['default_next']
            if default_next not in transitions:
                raise ValueError(f"default_next '{default_next}' of state '{state_name}' not in transitions")
            # Validate next_by_observation values if present
            if 'next_by_observation' in state_def:
                for obs, next_state in state_def['next_by_observation'].items():
                    if next_state not in transitions:
                        raise ValueError(f"next_by_observation '{obs}' -> '{next_state}' from state '{state_name}' not in transitions")
        else:
            raise ValueError(f"Invalid kind '{kind}' for state '{state_name}'")

    # Simulate ReAct loop
    current_state = initial_state
    step = 0
    trace = []

    while step < max_steps:
        state_def = transitions[current_state]
        if state_def['kind'] == 'final':
            break
        # Action state
        action = state_def['action']
        observation = tool_obs[action]
        next_by = state_def.get('next_by_observation', {})
        if observation in next_by:
            next_state = next_by[observation]
        else:
            next_state = state_def['default_next']
        step += 1
        trace.append({
            'step': step,
            'action': action,
            'observation': observation,
            'state': current_state
        })
        current_state = next_state

    # Determine final state
    if current_state in transitions and transitions[current_state]['kind'] == 'final':
        status = 'completed'
        final = transitions[current_state]['value']
    else:
        status = 'max_steps_reached'
        final = None

    return {
        'status': status,
        'final': final,
        'trace': trace
    }"
